-- 081 — Reprise du tableau Monday « UDI GESTION Suivi des Travaux T » dans les sinistres du pilotage (demande de Nicolas du 26/10).
-- « Travaux en cours de réalisation » (15) : sinistres ouverts. « Travaux finalisés » (190) : sinistres clos.
-- Le groupe « Travaux en attente de devis » n'est pas repris.
-- Rivage reste la source de vérité : rien n'est écrit dans Rivage. Ces dossiers vivent dans le pilotage, à côté des incidents Rivage,
-- et sont rattachés au bail et au mandat Rivage correspondants :
--   - par la référence bail/lot portée par le nom du bail Monday (« … - 269 - 241 » = bail 269, lot 241), sinon
--   - par le nom du locataire et l'adresse (ou le bailleur et la ville), le bail retenu étant celui en cours à la création du dossier.
-- La méthode de rattachement est gardée sur chaque dossier (colonne rattachement) pour pouvoir la contrôler.
-- Les mises à jour Monday (messages et réponses) sont chargées par 082 et 083. Les pièces jointes restent dans Monday.

begin;

create table if not exists pilotage.travaux_monday (
  monday_id bigint primary key,
  titre text not null,
  groupe text not null,
  clos boolean not null,
  statut_monday text,
  bail_id text,
  lot_id text,
  mandat_id text,
  rattachement text,
  monday_bail text,
  locataire text,
  adresse text,
  bailleur text,
  entreprises jsonb not null default '[]'::jsonb,
  gestionnaire text,
  intervention_le date,
  relance_le date,
  cree_le timestamptz not null,
  maj_monday_le timestamptz,
  clos_le date,
  url text,
  maj_par uuid,
  maj_le timestamptz
);

create table if not exists pilotage.travaux_monday_notes (
  id bigint generated always as identity primary key,
  monday_id bigint not null references pilotage.travaux_monday(monday_id) on delete cascade,
  monday_post_id bigint unique,
  parent_post_id bigint,
  parent_id bigint references pilotage.travaux_monday_notes(id) on delete cascade,
  auteur text,
  auteur_id uuid,
  le timestamptz not null default now(),
  contenu text not null,
  tronque boolean not null default false
);
create index if not exists travaux_monday_notes_dossier on pilotage.travaux_monday_notes (monday_id, le desc);

-- Lecture et écriture uniquement par les fonctions ci-dessous (même régime que les impayés)
alter table pilotage.travaux_monday enable row level security;
alter table pilotage.travaux_monday_notes enable row level security;
revoke all on pilotage.travaux_monday, pilotage.travaux_monday_notes from public, anon, authenticated;

-- Liste des sinistres : incidents Rivage (inchangés) + dossiers repris de Monday
create or replace function public.pilotage_sinistres() returns jsonb
language plpgsql stable security definer set search_path = pilotage, public as $function$
begin
  if pilotage.mon_role() is null then raise exception 'Accès refusé'; end if;
  return coalesce((
    select jsonb_agg(x order by (x->>'clos')::boolean, x->>'declare_le' desc) from (
      select jsonb_build_object(
        'id', i.id, 'source', 'rivage', 'numero', i.data->>'number', 'titre', i.data->>'title', 'description', i.data->>'description',
        'type', i.data->>'incident_type', 'urgence', i.data->>'urgency', 'statut', i.data->>'status',
        'clos', (i.data->>'status') in ('closed', 'resolved', 'cancelled') or i.data->>'archived_at' is not null,
        'declare_le', i.data->>'declared_at', 'resolu_le', left(i.data->>'resolved_at', 10), 'cree_le', i.data->>'created_at',
        'jours', (coalesce((i.data->>'resolved_at')::date, current_date) - (i.data->>'declared_at')::date),
        'a_charge', i.data->>'charged_to',
        'montant_estime', round((i.data->>'estimated_amount_in_cents')::numeric / 100, 2),
        'prestataires', jsonb_array_length(coalesce(i.data->'contractor_ids', '[]'::jsonb)),
        'prestataires_noms', (select coalesce(jsonb_agg(coalesce(pilotage.nom_profil(c), 'Prestataire inconnu du pilotage')), '[]'::jsonb)
                              from jsonb_array_elements_text(coalesce(i.data->'contractor_ids', '[]'::jsonb)) c),
        'adresse', l.adresse, 'lot', l.reference, 'locataires', b.locataires, 'bail', b.reference,
        'parties', coalesce(pilotage.contacts_bail(b.id), pilotage.contacts_mandat(l.mandat_id), '{}'::jsonb)
          || jsonb_build_object('entreprises', (select coalesce(jsonb_agg(jsonb_build_object('nom', coalesce(pilotage.nom_profil(c), 'Prestataire inconnu du pilotage'),
               'email', pr.data->>'email', 'telephone', pr.data->>'phone_number')), '[]'::jsonb)
             from jsonb_array_elements_text(coalesce(i.data->'contractor_ids', '[]'::jsonb)) c
             left join pilotage.objets pr on pr.type = 'Profile' and pr.id = c)),
        'bailleur', coalesce(pilotage.nom_profil(i.data->>'landlord_id'), pilotage.bailleurs_mandat(l.mandat_id)),
        'mandat', (select coalesce(nullif(m.nom, ''), 'Mandat n°' || m.reference) from pilotage.v_mandats m where m.id = l.mandat_id),
        'historique', pilotage.historique(i.id),
        'situation', pilotage.situation_lot(i.data->>'asset_id'),
        'mandat_statut', case (select m.statut from pilotage.v_mandats m where m.id = l.mandat_id)
                           when 'active' then 'Mandat actif' when 'lost' then 'Mandat perdu'
                           else case when i.data->>'asset_id' is null then null else 'Lot sans mandat' end end,
        'lien', 'https://rivage.immo/incidents/' || i.id
      ) x
      from pilotage.objets i
      left join pilotage.v_lots l on l.id = i.data->>'asset_id'
      left join pilotage.v_baux b on b.id = i.data->>'leasing_contract_id'
      where i.type = 'Incident' and i.supprime_le is null
        and pilotage.voit_tableau('sinistres', l.mandat_id)
      union all
      select jsonb_build_object(
        'id', 'monday_' || t.monday_id, 'source', 'monday', 'monday_id', t.monday_id, 'numero', null, 'titre', t.titre, 'description', null,
        'type', null, 'urgence', null, 'statut', case when t.clos then 'closed' else 'in_progress' end, 'statut_monday', t.statut_monday,
        'clos', t.clos, 'declare_le', to_char(t.cree_le, 'YYYY-MM-DD'), 'resolu_le', t.clos_le, 'cree_le', t.cree_le,
        'jours', (coalesce(t.clos_le, current_date) - t.cree_le::date),
        'a_charge', null, 'montant_estime', null,
        'prestataires', jsonb_array_length(t.entreprises),
        'prestataires_noms', (select coalesce(jsonb_agg(e->>'nom'), '[]'::jsonb) from jsonb_array_elements(t.entreprises) e),
        'adresse', coalesce(l.adresse, t.adresse), 'lot', l.reference, 'locataires', coalesce(b.locataires, t.locataire), 'bail', b.reference,
        'parties', coalesce(pilotage.contacts_bail(b.id), pilotage.contacts_mandat(mm.id), '{}'::jsonb)
          || jsonb_build_object('entreprises', (select coalesce(jsonb_agg(jsonb_build_object('nom', coalesce(pilotage.nom_profil(e->>'profil_id'), e->>'nom'),
               'email', pr.data->>'email', 'telephone', pr.data->>'phone_number')), '[]'::jsonb)
             from jsonb_array_elements(t.entreprises) e
             left join pilotage.objets pr on pr.type = 'Profile' and pr.id = e->>'profil_id')),
        'bailleur', coalesce(pilotage.bailleurs_mandat(mm.id), t.bailleur),
        'mandat', coalesce(nullif(mm.nom, ''), 'Mandat n°' || mm.reference),
        'historique', '[]'::jsonb,
        'situation', case when t.lot_id is not null then pilotage.situation_lot(t.lot_id) end,
        'mandat_statut', case mm.statut when 'active' then 'Mandat actif' when 'lost' then 'Mandat perdu'
                           else case when t.lot_id is null then null else 'Lot sans mandat' end end,
        'rattachement', t.rattachement, 'monday_bail', t.monday_bail, 'gestionnaire', t.gestionnaire,
        'nb_notes', (select count(*) from pilotage.travaux_monday_notes n where n.monday_id = t.monday_id),
        'derniere_note', (select max(n.le) from pilotage.travaux_monday_notes n where n.monday_id = t.monday_id),
        'lien', t.url
      ) x
      from pilotage.travaux_monday t
      left join pilotage.v_baux b on b.id = t.bail_id
      left join pilotage.v_lots l on l.id = coalesce(t.lot_id, b.lot_id)
      left join pilotage.v_mandats mm on mm.id = coalesce(t.mandat_id, l.mandat_id)
      where pilotage.voit_tableau('sinistres', mm.id)
    ) t
  ), '[]'::jsonb);
end $function$;

-- Fil des mises à jour d'un dossier repris de Monday (plus récent en premier)
create or replace function public.pilotage_travaux_notes(p_monday bigint) returns jsonb
language plpgsql stable security definer set search_path = pilotage, public as $function$
begin
  if pilotage.mon_role() is null then raise exception 'Accès refusé'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', n.id, 'parent_id', n.parent_id, 'auteur', n.auteur, 'le', n.le,
            'contenu', n.contenu, 'tronque', n.tronque, 'monday', n.monday_post_id is not null) order by n.le desc)
          from pilotage.travaux_monday_notes n where n.monday_id = p_monday), '[]'::jsonb);
end $function$;

-- Nouvelle mise à jour écrite dans le pilotage (le suivi continue ici, plus dans Monday)
create or replace function public.pilotage_travaux_note(p_monday bigint, p_contenu text) returns void
language plpgsql security definer set search_path = pilotage, public as $function$
begin
  if pilotage.mon_role() is null then raise exception 'Accès refusé'; end if;
  if nullif(trim(p_contenu), '') is null then raise exception 'Mise à jour vide'; end if;
  if not exists (select 1 from pilotage.travaux_monday where monday_id = p_monday) then raise exception 'Dossier introuvable'; end if;
  insert into pilotage.travaux_monday_notes (monday_id, auteur, auteur_id, contenu)
  select p_monday, m.prenom, auth.uid(), trim(p_contenu) from pilotage.membres m where m.user_id = auth.uid();
  update pilotage.travaux_monday set maj_par = auth.uid(), maj_le = now() where monday_id = p_monday;
end $function$;

-- Clore ou rouvrir un dossier repris de Monday
create or replace function public.pilotage_travaux_clore(p_monday bigint, p_clos boolean) returns void
language plpgsql security definer set search_path = pilotage, public as $function$
begin
  if pilotage.mon_role() is null then raise exception 'Accès refusé'; end if;
  update pilotage.travaux_monday set clos = p_clos, clos_le = case when p_clos then current_date end, maj_par = auth.uid(), maj_le = now()
  where monday_id = p_monday;
  if not found then raise exception 'Dossier introuvable'; end if;
  insert into pilotage.travaux_monday_notes (monday_id, auteur, auteur_id, contenu)
  select p_monday, m.prenom, auth.uid(), case when p_clos then 'Dossier clos dans le pilotage.' else 'Dossier rouvert dans le pilotage.' end
  from pilotage.membres m where m.user_id = auth.uid();
end $function$;

revoke all on function public.pilotage_travaux_notes(bigint), public.pilotage_travaux_note(bigint, text), public.pilotage_travaux_clore(bigint, boolean) from public, anon;
grant execute on function public.pilotage_travaux_notes(bigint), public.pilotage_travaux_note(bigint, text), public.pilotage_travaux_clore(bigint, boolean) to authenticated;

