-- Contrôle (attendu : 15 ouverts, 190 clos ; 198 rattachés à un bail, 3 à un lot seul, 4 sans rattachement)
select clos, count(*) dossiers, count(bail_id) avec_bail, count(*) filter (where bail_id is null and coalesce(lot_id, mandat_id) is not null) lot_ou_mandat_seul,
       count(*) filter (where coalesce(bail_id, lot_id, mandat_id) is null) sans_rattachement
from pilotage.travaux_monday group by clos order by clos;
